const text=(key,label)=>({key,label,type:'textarea'})
const short=(key,label,type='text')=>({key,label,type})
const checks=(key,label,options)=>({key,label,type:'checks',options})
// Source labels are retained while these codes remain stable across report revisions.
const codedChecks=(key,label,options)=>checks(key,label,options.map(([value,label])=>({value,label})))
const count=(key,label)=>({key,label,type:'number'})
const copy=value=>value===undefined?undefined:JSON.parse(JSON.stringify(value))
const supplied=(object,key,fallback='')=>Object.hasOwn(object||{},key)?copy(object[key]):fallback
const note=value=>value==null||value===''?'Unknown':Array.isArray(value)?value.join('; '):typeof value==='object'?JSON.stringify(value,null,2):String(value)
