export function initializeFields(values={}){
 const result={...values}
 for(const group of maicGroups)for(const field of group.fields){
  if(field.type==='checks' && result[field.key]===undefined)result[field.key]=[]
  if(field.type==='number' && (result[field.key]===undefined || result[field.key]===''))result[field.key]=null
 }
 return result
}
export function initialFields(event){
 const fields={occurrenceDate:event.dateUnknown?'':event.date,occurrenceTime:event.timeUnknown?'':event.time,place:event.place,position:`${event.lat ?? 'Unknown'}, ${event.lon ?? 'Unknown'} · ${event.positionQuality}`,incidentTypes:[event.type,...(event.secondaryTypes || [])].join(', '),seriousness:event.seriousness,aor:event.aor,homeport:event.homeport,cpc:event.cpc,issuingOffice:event.issuingOffice,occurrenceNarrative:[event.summary,event.timeline?`Reported timeline:\n${event.timeline}`:'',event.crewResponse?`Reported crew response:\n${event.crewResponse}`:''].filter(value=>value!==undefined&&value!==null&&value!=='').join('\n\n'),initialActions:event.initialActions,recommendations:event.recommendations,informationSources:[event.sourceType,event.sourceRef,event.reportingAuthority?`Reporting authority: ${event.reportingAuthority}`:'',event.sourceNotes?`Source notes: ${event.sourceNotes}`:'',event.documentNotes?`Document notes: ${event.documentNotes}`:''].filter(value=>value!==undefined&&value!==null&&value!=='').join(' · '),machineryFactors:[],humanFactors:[],environmentFactors:[]}
 for(const k of ['fatalities','missing','injured','rescued','crew','passengers','totalOnboard']) fields[k]=event.consequences?.[k] ?? null
 fields.damage=[event.consequences?.shipCondition,event.damageTypes?.length?`Reported damage types: ${note(event.damageTypes)}`:''].filter(value=>value!==undefined&&value!==null&&value!=='').join('\n');fields.pollution=supplied(event.consequences,'pollution');fields.rescueRecovery=supplied(event,'rescueRecovery');fields.certificates=supplied(event,'certificates')
 for(const key of ['timeline','crewResponse','potentialCauses','findingsOfCause','reportingAuthority','sourceNotes','documentNotes'])fields[key]=supplied(event,key)
 fields.crewFactors=supplied(event,'crewFactors',[]);fields.damageTypes=supplied(event,'damageTypes',[]);fields.reportedCrewFactors=note(fields.crewFactors);fields.reportedDamageTypes=note(fields.damageTypes)
 fields.primaryCauseEvidence=event.potentialCauses?`Preliminary potential causes reported — not established findings:\n${note(event.potentialCauses)}`:''
 fields.consequenceObservedAt=supplied(event.consequences,'observedAt',null);fields.consequenceSourceNotes=supplied(event.consequences,'notes')
 fields.environment=copy(event.environment||{})
 for(const key of ['waveHeightM','windForce','visibility','weatherDescription','seaState','currentTide'])fields[key]=supplied(event.environment,key,null)
 fields.environmentObservedAt=supplied(event.environment,'observedAt',null)
 fields.environmentSource=supplied(event.environment,'source')
 fields.environmentFieldSources=supplied(event.environment,'fieldSources',{})
 fields.environmentValueProvenance=[['waveHeightM','Wave height (m)'],['windForce','Wind force'],['visibility','Visibility / unit'],['weatherDescription','Weather description'],['seaState','Sea state'],['currentTide','Current / tide']].map(([key,label])=>`${label}: ${describeEnvironmentField(event.environment||{},key)}`).join('\n')
 const lookup=supplied(event.environment,'lookup',null);fields.modelledEnvironmentLookup=lookup===null||lookup===undefined||lookup===''?'No modelled lookup retained.':`Retained lookup reference only — not an on-scene observation. Applied value sources are recorded separately. Retained provenance:\n${note(lookup)}`
 fields.shipParticulars=event.vessels.map(v=>`${v.name || 'Unknown vessel'}; former names: ${v.formerNames || 'Unknown'}; Official: ${v.officialNumber || 'Unknown'}; IMO: ${v.imoNumber || 'Unknown'}; registration: ${v.registrationStatus || 'Unknown'}; rig: ${v.rigType || 'Unknown'}; service: ${v.type || 'Unknown'}; flag: ${v.flag || 'Unknown'}; port of registry (place): ${v.portOfRegistry || 'Unknown'}`).join('\n\n')
 fields.construction=event.vessels.map(v=>`${v.name}: built ${v.yearBuilt ?? 'Unknown'} at ${v.buildPlace || 'Unknown'}; hull ${v.hull || 'Unknown'}; L/B/D ${v.length ?? '?'}/${v.breadth ?? '?'}/${v.depth ?? '?'}; GT ${v.grossTonnage ?? 'Unknown'} / NT ${v.netTonnage ?? 'Unknown'} / DWT ${v.deadweight ?? 'Unknown'}; size ${v.sizeClass || 'Unknown'}; class ${v.classificationSociety || 'Unknown'}`).join('\n\n')
 fields.machineryParticulars=event.vessels.map(v=>`${v.name}: propulsion type ${v.propulsionType || 'Unknown'}; ${v.engineCount ?? 'Unknown count'} engines; ${v.engineMake || 'Unknown make'}; ${v.enginePower ?? 'Unknown power'} ${v.enginePowerUnit || ''}; stern ${v.sternType || 'Unknown'}`).join('\n\n')
 fields.ownership=event.vessels.map(v=>`${v.name}: owner ${v.owner || 'Unknown'}; operator ${v.operator || 'Unknown'}; contacts ${v.ownerContact || 'Unknown'} / ${v.operatorAddress || 'Unknown'}; homeport (place) ${v.homeportPlace || 'Unknown'}; homeport office ${v.homeport || 'Unknown'}; CPC office ${v.cpc || 'Unknown'}; master ${v.masterName || 'Unknown'} / licence ${v.masterLicense || 'Unknown'}`).join('\n\n')
 fields.voyage=event.vessels.map(v=>`${v.name}: ${v.voyage?.origin || 'Unknown origin'} to ${v.voyage?.destination || 'Unknown destination'}; route ${v.voyage?.route || 'Unknown'}; cargo ${v.voyage?.cargoType || 'Unknown'} ${v.voyage?.cargoQuantity ?? ''} ${v.voyage?.cargoUnit || ''}`).join('\n\n')
 const overrides=copy(event.maicFields&&typeof event.maicFields==='object'&&!Array.isArray(event.maicFields)?event.maicFields:{})
 const result={...initializeFields(fields),...overrides}
 if(!Object.hasOwn(overrides,'environmentValueProvenance')){const valueEnvironment={...(result.environment||{}),fieldSources:result.environmentFieldSources,...Object.fromEntries(['waveHeightM','windForce','visibility','weatherDescription','seaState','currentTide'].map(key=>[key,result[key]]))};result.environmentValueProvenance=[['waveHeightM','Wave height (m)'],['windForce','Wind force'],['visibility','Visibility / unit'],['weatherDescription','Weather description'],['seaState','Sea state'],['currentTide','Current / tide']].map(([key,label])=>`${label}: ${describeEnvironmentField(valueEnvironment,key)}`).join('\n')}
 return result
}
